import subprocess, time, sys
SOCK="testkiro"
def tmux(*a):
    r=subprocess.run(["tmux","-L",SOCK]+list(a), capture_output=True, text=True)
    return r
def cap(e=False):
    args=["capture-pane","-t","s","-p"]
    if e: args.append("-e")
    # also -J? maybe
    return tmux(*args).stdout
def cursor():
    return tmux("display-message","-t","s","-p","#{cursor_x} #{cursor_y} #{cursor_character}").stdout.strip()
def send(*ks):
    for k in ks:
        tmux("send-keys","-t","s",k); time.sleep(0.08)
    time.sleep(0.25)
def sendl(t):
    # literal chunk
    tmux("send-keys","-t","s","-l",t); time.sleep(0.25)
def start(cmd="./executable", w=80, h=24, env=None):
    tmux("kill-server"); time.sleep(0.2)
    tmux("new-session","-d","-s","s","-x",str(w),"-y",str(h))
    if env:
        cmd = env+" "+cmd
    tmux("send-keys","-t","s", cmd, "Enter")
    time.sleep(0.5)
def kill(): tmux("kill-server")
def show():
    print(cap())
    print(f"---cursor {cursor()}---")
