import subprocess, time
SOCK="testkiro"
def tmux(*a):
    return subprocess.run(["tmux","-L",SOCK]+list(a), capture_output=True, text=True)
def cap(e=False):
    args=["capture-pane","-t","s","-p"]
    if e: args.append("-e")
    return tmux(*args).stdout
def cursor():
    return tmux("display-message","-t","s","-p","#{cursor_x} #{cursor_y}").stdout.strip()
def start(cmd="./executable", w=80, h=24):
    tmux("kill-server"); time.sleep(0.15)
    tmux("new-session","-d","-s","s","-x",str(w),"-y",str(h))
    tmux("send-keys","-t","s",cmd,"Enter"); time.sleep(0.4)
def kill(): tmux("kill-server")
def send(*ks):
    for k in ks: tmux("send-keys","-t","s",k); time.sleep(0.04)
    time.sleep(0.2)
def sendl(t):
    tmux("send-keys","-t","s","-l",t); time.sleep(0.2)
def sendhex(bs):
    # bs bytes
    hexes=[f"{b:02x}" for b in bs]
    tmux("send-keys","-t","s","-H",*hexes); time.sleep(0.25)
def show(label=""):
    print(f"--- {label} cursor={cursor()} ---")
    for i,l in enumerate(cap().splitlines()): print(f"{i:2}|{l}")
def lines():
    return cap().splitlines()
def status_msg():
    ls=lines(); return (ls[-2] if len(ls)>=2 else "", ls[-1] if ls else "")
