import sys, re
sys.path.insert(0,'/tmp')
from ptytest import run_pty

COLOR_NAMES={"90":"comment","94":"keyword","93":"ident","33":"type","95":"number","32":"string","91":"control","96":"special","37":"nontext"}

def segments_for_file(path, rows=30, cols=200):
    outs,st=run_pty(["./executable",path],[],rows=rows,cols=cols)
    data=outs[0]
    # split by row goto markers \x1b[<n>H
    parts=re.split(rb'\x1b\[(\d+)H',data)
    # parts: before, rowno, content,...
    rowsd={}
    for i in range(1,len(parts),2):
        rn=int(parts[i]); content=parts[i+1] if i+1<len(parts) else b""
        # content until next split already, but status row etc may include cursor sequence; strip at \x1b[?25h maybe
        rowsd[rn]=content
    result=[]
    for rn in sorted(rowsd):
        content=rowsd[rn]
        # tokenise escapes and text
        segs=[]; cur="normal"
        i=0
        while i < len(content):
            if content[i:i+1]==b'\x1b':
                m=re.match(rb'\x1b\[([0-9;?]*)([A-Za-z])',content[i:])
                if m:
                    params,final=m.group(1).decode(),m.group(2).decode()
                    if final=='m':
                        if params in ("39;0","0","39"): cur="normal"
                        elif params in COLOR_NAMES: cur=COLOR_NAMES[params]
                        else: cur=f"color{params}"
                    i += len(m.group(0)); continue
                else:
                    i+=1; continue
            j=content.find(b'\x1b',i)
            if j==-1:j=len(content)
            txt=content[i:j].decode(errors="replace")
            if txt: segs.append((cur,txt))
            i=j
        result.append(segs)
    return result

def classify_words(path):
    rows=segments_for_file(path)
    out=[]
    for segs in rows:
        # join segment words: words are split in original by spaces; assign color of first segment overlapping word? collect segment list excluding status/message rows by caller slices
        out.append(segs)
    return out

def word_colors(ext, words, per_line=8):
    lines=[]
    for i in range(0,len(words),per_line):
        lines.append(' '.join(words[i:i+per_line]))
    path=f"/tmp/testdir/syn/words.{ext}"
    open(path,"w").write('\n'.join(lines)+'\n')
    rows=segments_for_file(path, rows=len(lines)+3)
    # First len(lines) screen rows are content
    res={}
    for li,line in enumerate(lines):
        segs=rows[li]
        # walk chars with colors
        chars=[]
        for color,txt in segs:
            for ch in txt: chars.append((ch,color))
        # chars may not include trailing after clear; map each word by searching global char positions according line text (render same no tabs)
        pos=0
        for w in line.split(' '):
            if not w: pos+=1; continue
            # Find word starting at pos in chars
            colors=[]
            for k,ch in enumerate(w):
                if pos+k < len(chars): colors.append(chars[pos+k][1])
            # unique non-normal or first
            uniq=[]
            for c in colors:
                if c not in uniq: uniq.append(c)
            res[w]='/'.join(uniq) if uniq else '?'
            pos += len(w)+1
    return res
