use crate::error::{Error, Result};
use std::fs::File;
use std::io::Read;
use std::os::unix::io::FromRawFd;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Key {
    Char(char),
    Ctrl(char),
    Alt(char),
    Escape,
    Backspace,
    Delete,
    Up,
    Down,
    Left,
    Right,
    CtrlUp,
    CtrlDown,
    CtrlLeft,
    CtrlRight,
    Home,
    End,
    CtrlHome,
    CtrlEnd,
    PageUp,
    PageDown,
}

impl Key {
    pub fn name(&self) -> String {
        match self {
            Key::Char(c) => c.to_string(),
            Key::Ctrl(c) => {
                if *c == ' ' {
                    "C-SPACE".to_string()
                } else {
                    format!("C-{}", c)
                }
            }
            Key::Alt(c) => {
                if c.is_control() {
                    // Alt together with a control character.
                    let n = ctrl_name_char(*c);
                    if n == ' ' {
                        "M-C-SPACE".to_string()
                    } else {
                        format!("M-C-{}", n)
                    }
                } else if *c == '\x7f' {
                    "M-BACKSPACE".to_string()
                } else {
                    format!("M-{}", c)
                }
            }
            Key::Escape => "ESC".to_string(),
            Key::Backspace => "BACKSPACE".to_string(),
            Key::Delete => "DELETE".to_string(),
