fn starts_with_at(chars: &[char], i: usize, pat: &str) -> Option<usize> {
    let pc: Vec<char> = pat.chars().collect();
    if chars.len() - i >= pc.len() && chars[i..i + pc.len()] == pc[..] {
        Some(pc.len())
    } else {
        None
    }
}

fn scan_number(chars: &[char], start: usize, syntax: &SyntaxDef) -> usize {
    let n = chars.len();
    let get = |i: usize| chars.get(i).copied();
    // Hexadecimal.
    if get(start) == Some('0')
        && get(start + 1) == Some('x')
        && get(start + 2).map_or(false, |c| c.is_ascii_hexdigit())
    {
        let mut i = start + 2;
        while i < n
            && (chars[i].is_ascii_hexdigit() || (syntax.underscore_numbers && chars[i] == '_'))
        {
            i += 1;
        }
        return i;
    }
    // Binary.
    if syntax.binary_numbers
        && get(start) == Some('0')
        && get(start + 1) == Some('b')
        && matches!(get(start + 2), Some('0') | Some('1'))
    {
        let mut i = start + 2;
        while i < n
            && (matches!(chars[i], '0' | '1') || (syntax.underscore_numbers && chars[i] == '_'))
        {
            i += 1;
        }
        return i;
    }
    let mut i = start;
    while i < n && (chars[i].is_ascii_digit() || (syntax.underscore_numbers && chars[i] == '_')) {
        i += 1;
    }
    if get(i) == Some('.') {
        i += 1;
        while i < n && chars[i].is_ascii_digit() {
            i += 1;
        }
        // A further dotted section (for example 1.2.3) is
        // highlighted as part of the number, but "1..2" stops
        // after the first dot.
        while get(i) == Some('.') && get(i + 1).map_or(false, |c| c.is_ascii_digit()) {
            i += 1;
            while i < n && chars[i].is_ascii_digit() {
                i += 1;
            }
        }
    }
    i
}

fn compute_row(render: &str, syntax: &SyntaxDef, state: &mut HlState) -> Vec<Highlight> {
    let chars: Vec<char> = render.chars().collect();
    let n = chars.len();
    let mut hl = vec![Highlight::Normal; n];
    let mut is_ident = false;
    let mut prev_sep = true;
    let mut i = 0usize;

    while i < n {
        let c = chars[i];

        if state.in_comment {
            hl[i] = Highlight::Comment;
            if let Some((_, end)) = syntax.multi_comment {
                if let Some(len) = starts_with_at(&chars, i, end) {
                    for k in 0..len {
                        hl[i + k] = Highlight::Comment;
                    }
                    i += len;
                    state.in_comment = false;
                    prev_sep = true;
                    continue;
                }
            }
            i += 1;
            continue;
        }

        if let Some(delim) = state.in_string {
            hl[i] = Highlight::String;
            if c == '\\' && i + 1 < n {
                hl[i + 1] = Highlight::String;
                i += 2;
                continue;
            }
            if c == delim {
                state.in_string = None;
            }
            i += 1;
            prev_sep = true;
            continue;
        }

        if let Some(scp) = syntax.single_comment {
            if starts_with_at(&chars, i, scp).is_some() {
                for item in hl.iter_mut().skip(i) {
                    *item = Highlight::Comment;
                }
                break;
            }
        }

        if let Some((mstart, _)) = syntax.multi_comment {
            if let Some(len) = starts_with_at(&chars, i, mstart) {
                for k in 0..len {
                    hl[i + k] = Highlight::Comment;
                }
                i += len;
                state.in_comment = true;
                prev_sep = true;
                continue;
            }
        }

        if (syntax.double_quote && c == '"') || (syntax.backtick_quote && c == '`') {
            state.in_string = Some(c);
            hl[i] = Highlight::String;
            i += 1;
            continue;
        }

        if c == '\'' {
            match syntax.single_quote {
                SingleQuoteKind::String => {
                    state.in_string = Some(c);
                    hl[i] = Highlight::String;
                    i += 1;
                    continue;
                }
                SingleQuoteKind::CharLiteral => {
                    let lit_len = if i + 2 < n && chars[i + 2] == '\'' {
                        Some(3)
                    } else if i + 3 < n && chars[i + 1] == '\\' && chars[i + 3] == '\'' {
                        Some(4)
                    } else {
                        None
                    };
                    if let Some(len) = lit_len {
                        for k in 0..len {
                            hl[i + k] = Highlight::String;
                        }
                        i += len;
                        prev_sep = true;
                        continue;
                    }
                }
                SingleQuoteKind::None => {}
            }
            // An ordinary punctuation character.
            is_ident = false;
            prev_sep = true;
            i += 1;
            continue;
        }

        if c.is_ascii_digit() && prev_sep {
            let end = scan_number(&chars, i, syntax);
            let cat = if is_ident {
                Highlight::Identifier
            } else {
                Highlight::Number
            };
            for item in hl.iter_mut().take(end).skip(i) {
                *item = cat;
            }
            i = end;
            prev_sep = false;
            continue;
        }

        if c.is_alphabetic() || c == '_' {
            let start = i;
            let mut token = String::new();
            while i < n && (chars[i].is_alphanumeric() || chars[i] == '_') {
                token.push(chars[i]);
                i += 1;
            }
            let cat = if syntax.constants.contains(&token.as_str()) {
                Highlight::Number
            } else if syntax.specials.contains(&token.as_str()) {
                Highlight::Special
            } else if syntax.types.contains(&token.as_str()) {
                Highlight::Type
            } else if syntax.controls.contains(&token.as_str()) {
                Highlight::Control
            } else if syntax.keywords.contains(&token.as_str()) {
                Highlight::Keyword
            } else if is_ident {
                Highlight::Identifier
            } else {
                Highlight::Normal
            };
            if cat != Highlight::Normal {
                // The original implementation marked a number of
                // highlight slots equal to the token byte length.
                // This is observable for non-ASCII identifiers.
                for k in 0..token.len() {
                    *hl.get_mut(start + k).unwrap() = cat;
                }
            }
            if syntax.ident_triggers.contains(&token.as_str()) {
                is_ident = true;
            }
            prev_sep = false;
            continue;
        }

        if c.is_whitespace() {
            prev_sep = true;
        } else {
            prev_sep = true;
            is_ident = false;
        }
        i += 1;
    }
    hl
}
