pub fn syntax_for_filename(filename: Option<&str>) -> SyntaxDef {
    let Some(name) = filename else {
        return PLAIN.clone();
    };
    let path = std::path::Path::new(name);
    let Some(ext) = path.extension().and_then(|e| e.to_str()) else {
        return PLAIN.clone();
    };
    for syn in SYNTAXES {
        if syn.extensions.contains(&ext) {
            return syn.clone();
        }
    }
