use crate::width::char_width;

pub const TAB_STOP: usize = 8;

#[derive(Debug, Clone)]
pub struct Row {
    pub chars: String,
    pub render: String,
    pub hl: Vec<Highlight>,
}

impl Row {
    pub fn new(chars: String) -> Result<Self> {
        for c in chars.chars() {
            if c.is_control() && c != '\t' && c != '\0' {
                return Err(Error::Message(format!(
                    "Invalid character for text is included: {:?}",
                    c
                )));
            }
        }
        let mut row = Row {
            render: String::new(),
            hl: Vec::new(),
            chars,
        };
        row.update_render();
        Ok(row)
    }

    pub fn from_edit(chars: String) -> Self {
        // Rows created by splitting or joining existing rows have
        // already been validated.
        let mut row = Row {
            render: String::new(),
            hl: Vec::new(),
            chars,
        };
        row.update_render();
        row
    }

    pub fn update_render(&mut self) {
        let mut render = String::new();
        let mut rx = 0usize;
        for c in self.chars.chars() {
            if c == '\t' {
                let spaces = TAB_STOP - (rx % TAB_STOP);
                for _ in 0..spaces {
                    render.push(' ');
                }
                rx += spaces;
            } else {
                render.push(c);
                rx += char_width(c);
            }
        }
        self.render = render;
        self.hl = vec![Highlight::Normal; self.render.chars().count()];
    }

    pub fn len(&self) -> usize {
        self.chars.len()
    }

    pub fn is_empty(&self) -> bool {
        self.chars.is_empty()
    }

    pub fn cx_to_rx(&self, cx: usize) -> usize {
        let mut rx = 0usize;
        for c in self.chars[..cx].chars() {
            if c == '\t' {
                rx += TAB_STOP - (rx % TAB_STOP);
            } else {
                rx += char_width(c);
            }
        }
        rx
    }

    /// Convert a byte index in `render` to a byte index in `chars`.
    pub fn render_byte_to_cx(&self, render_byte: usize) -> usize {
        // Walk the original characters and the rendered form in
        // parallel. Tabs in the original expand to spaces.
        let mut cur_render_byte = 0usize;
        let mut rx = 0usize;
        for (byte_idx, c) in self.chars.char_indices() {
            if cur_render_byte >= render_byte {
                return byte_idx;
            }
            if c == '\t' {
                let spaces = TAB_STOP - (rx % TAB_STOP);
                // Each rendered space is one byte.
                if render_byte < cur_render_byte + spaces {
                    return byte_idx;
                }
                cur_render_byte += spaces;
                rx += spaces;
            } else {
                if render_byte < cur_render_byte + c.len_utf8() {
                    return byte_idx;
                }
                cur_render_byte += c.len_utf8();
                rx += char_width(c);
            }
        }
        self.chars.len()
    }

    /// Convert a byte index in `chars` to a byte index in `render`.
    pub fn cx_to_render_byte(&self, cx: usize) -> usize {
        let mut render_byte = 0usize;
        let mut rx = 0usize;
        for c in self.chars[..cx].chars() {
            if c == '\t' {
                let spaces = TAB_STOP - (rx % TAB_STOP);
                render_byte += spaces;
                rx += spaces;
            } else {
                render_byte += c.len_utf8();
                rx += char_width(c);
            }
        }
        render_byte
    }
}
