use crate::error::{Error, Result};
use crate::highlight::Highlight;
use crate::input::InputReader;
use std::io::{self, Write};
use std::path::PathBuf;
use termios::{cfmakeraw, tcsetattr, Termios, TCSANOW};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorMode {
    Basic,
    Color256,
    TrueColor,
}

pub struct Screen {
    original: Termios,
    stdout: io::Stdout,
    entered_alt: bool,
    pub mode: ColorMode,
    pub cols: usize,
    pub term_rows: usize,
    pub text_rows: usize,
}

impl Screen {
    pub fn new(input: &mut InputReader) -> Result<Self> {
        let original = Termios::from_fd(0)?;
        let mut raw = original.clone();
        cfmakeraw(&mut raw);
        tcsetattr(0, TCSANOW, &raw)?;

        let mut screen = Screen {
            original,
            stdout: io::stdout(),
            entered_alt: false,
            mode: detect_color_mode(),
            cols: 0,
            term_rows: 0,
            text_rows: 0,
        };
        let (cols, rows) = screen.get_window_size(input)?;
        validate_size(cols, rows)?;
        screen.cols = cols;
        screen.term_rows = rows;
        screen.text_rows = rows - 2;
        screen.stdout.write_all(b"\x1b[?1049h")?;
        screen.stdout.flush()?;
        screen.entered_alt = true;
        Ok(screen)
    }

    pub fn get_window_size(&mut self, input: &mut InputReader) -> Result<(usize, usize)> {
        #[repr(C)]
        #[derive(Default)]
        struct Winsize {
            ws_row: libc::c_ushort,
            ws_col: libc::c_ushort,
            ws_xpixel: libc::c_ushort,
            ws_ypixel: libc::c_ushort,
        }
        let mut ws = Winsize::default();
        let ret = unsafe { libc::ioctl(1, libc::TIOCGWINSZ, &mut ws as *mut Winsize) };
        if ret == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
            return Ok((ws.ws_col as usize, ws.ws_row as usize));
        }
        self.stdout.write_all(b"\x1b[9999C\x1b[9999B\x1b[6n")?;
        self.stdout.flush()?;
        let (rows, cols) = input.read_cursor_position()?;
        Ok((cols, rows))
    }

    pub fn write_bytes(&mut self, bytes: &[u8]) -> Result<()> {
        self.stdout.write_all(bytes)?;
        self.stdout.flush()?;
        Ok(())
    }

    pub fn write_str_flush(&mut self, s: &str) -> Result<()> {
        self.write_bytes(s.as_bytes())
    }

    pub fn normal_seq(&self) -> String {
        match self.mode {
            ColorMode::Basic => "\x1b[39;0m".to_string(),
            ColorMode::Color256 => "\x1b[39;0m\x1b[38;5;230m\x1b[48;5;235m".to_string(),
            ColorMode::TrueColor => {
                "\x1b[39;0m\x1b[38;2;251;241;199m\x1b[48;2;40;40;40m".to_string()
            }
        }
    }

    pub fn fg_seq(&self, hl: Highlight) -> String {
        match self.mode {
            ColorMode::Basic => {
                let code = match hl {
                    Highlight::Normal => return self.normal_seq(),
                    Highlight::NonText => 37,
                    Highlight::Comment => 90,
                    Highlight::Keyword => 94,
                    Highlight::Control => 91,
                    Highlight::Type => 33,
                    Highlight::Number => 95,
                    Highlight::String => 32,
                    Highlight::Identifier => 93,
                    Highlight::Special => 96,
                    Highlight::SearchCurrent | Highlight::SearchOther => 30,
                };
                format!("\x1b[{}m", code)
            }
            ColorMode::Color256 => {
                let code = match hl {
                    Highlight::Normal => return self.normal_seq(),
                    Highlight::NonText => 241,
                    Highlight::Comment => 246,
                    Highlight::Keyword => 109,
                    Highlight::Control => 167,
                    Highlight::Type => 208,
                    Highlight::Number => 175,
                    Highlight::String => 142,
                    Highlight::Identifier => 214,
                    Highlight::Special => 108,
                    Highlight::SearchCurrent | Highlight::SearchOther => 235,
                };
                format!("\x1b[38;5;{}m", code)
            }
            ColorMode::TrueColor => {
                let (r, g, b) = match hl {
                    Highlight::Normal => return self.normal_seq(),
                    Highlight::NonText => (102, 92, 84),
                    Highlight::Comment => (168, 153, 132),
                    Highlight::Keyword => (131, 165, 152),
                    Highlight::Control => (251, 73, 52),
                    Highlight::Type => (254, 128, 25),
                    Highlight::Number => (211, 134, 155),
                    Highlight::String => (184, 187, 38),
                    Highlight::Identifier => (250, 189, 47),
                    Highlight::Special => (142, 192, 124),
                    Highlight::SearchCurrent | Highlight::SearchOther => (40, 40, 40),
                };
                format!("\x1b[38;2;{};{};{}m", r, g, b)
            }
        }
    }

    pub fn search_seq(&self, hl: Highlight) -> String {
        match self.mode {
            ColorMode::Basic => {
                let bg = if hl == Highlight::SearchCurrent {
                    107
                } else {
                    103
                };
                // In the basic palette the background code is
                // emitted before the foreground code.
                format!("\x1b[{}m\x1b[30m", bg)
            }
            ColorMode::Color256 => {
                let bg = if hl == Highlight::SearchCurrent {
                    166
                } else {
                    214
                };
                format!("\x1b[38;5;235m\x1b[48;5;{}m", bg)
            }
            ColorMode::TrueColor => {
                let bg = if hl == Highlight::SearchCurrent {
                    "214;93;14"
                } else {
                    "215;153;33"
                };
                format!("\x1b[38;2;40;40;40m\x1b[48;2;{}m", bg)
            }
        }
    }

    pub fn color_seq(&self, hl: Highlight) -> String {
        if matches!(hl, Highlight::SearchCurrent | Highlight::SearchOther) {
            self.search_seq(hl)
        } else if hl == Highlight::Normal {
            self.normal_seq()
        } else {
            self.fg_seq(hl)
        }
    }

    pub fn error_seq(&self) -> String {
        match self.mode {
            ColorMode::Basic => "\x1b[97m\x1b[41m".to_string(),
            ColorMode::Color256 => "\x1b[38;5;230m\x1b[48;5;124m".to_string(),
            ColorMode::TrueColor => "\x1b[38;2;251;241;199m\x1b[48;2;204;36;29m".to_string(),
        }
    }
}

impl Drop for Screen {
    fn drop(&mut self) {
        if self.entered_alt {
            let _ = self.stdout.write_all(b"\x1b[?1049l\x1b[H");
            let _ = self.stdout.flush();
        }
        let _ = tcsetattr(0, TCSANOW, &self.original);
    }
}

pub fn validate_size(cols: usize, rows: usize) -> Result<()> {
    if cols < 1 || rows < 3 {
        return Err(Error::Message(format!(
            "Screen {}x{} is too small. At least 1x3 is necessary in width x height",
            cols, rows
        )));
    }
    Ok(())
}

fn detect_color_mode() -> ColorMode {
    if std::env::var("COLORTERM").ok().as_deref() == Some("truecolor") {
        return ColorMode::TrueColor;
    }
    if let Some(colors) = terminfo_max_colors() {
        if colors >= 256 {
            return ColorMode::Color256;
        }
    }
    ColorMode::Basic
}

fn terminfo_max_colors() -> Option<i32> {
    let term = std::env::var("TERM").ok()?;
    if term.is_empty() {
        return None;
    }
    let mut roots: Vec<PathBuf> = Vec::new();
    if let Ok(ti) = std::env::var("TERMINFO") {
        if !ti.is_empty() {
            roots.push(PathBuf::from(ti));
        }
    }
    if let Ok(home) = std::env::var("HOME") {
        if !home.is_empty() {
            roots.push(PathBuf::from(home).join(".terminfo"));
        }
    }
    if let Ok(dirs) = std::env::var("TERMINFO_DIRS") {
        for d in dirs.split(':') {
            if d.is_empty() {
                roots.push(PathBuf::from("/usr/share/terminfo"));
            } else {
                roots.push(PathBuf::from(d));
            }
        }
    } else {
        roots.push(PathBuf::from("/etc/terminfo"));
        roots.push(PathBuf::from("/lib/terminfo"));
        roots.push(PathBuf::from("/usr/share/terminfo"));
    }

    let first = term.chars().next()?;
    let hex = format!("{:02x}", first as u32);
    for root in roots {
        let mut candidates = vec![];
        if root.is_file() {
            candidates.push(root.clone());
        } else {
            candidates.push(root.join(first.to_string()).join(&term));
            candidates.push(root.join(hex.clone()).join(&term));
        }
        for cand in candidates {
            if let Ok(data) = std::fs::read(&cand) {
                if let Some(v) = parse_terminfo_colors(&data) {
                    return Some(v);
                }
            }
        }
    }
    None
}

fn parse_terminfo_colors(data: &[u8]) -> Option<i32> {
    if data.len() < 12 {
        return None;
    }
    let read_u16 = |off: usize| -> Option<u16> {
        Some(u16::from_le_bytes([*data.get(off)?, *data.get(off + 1)?]))
    };
    let magic = read_u16(0)?;
    let num_size: usize = if magic == 542 {
        4
    } else if magic == 282 {
        2
    } else {
        return None;
    };
    let name_size = read_u16(2)? as usize;
    let bool_count = read_u16(4)? as usize;
    let num_count = read_u16(6)? as usize;
    if num_count <= 13 {
        return None;
    }
    let mut off = 12 + name_size + bool_count;
    if off % 2 == 1 {
        off += 1;
    }
    let idx_off = off + 13 * num_size;
    if num_size == 2 {
        let v = i16::from_le_bytes([*data.get(idx_off)?, *data.get(idx_off + 1)?]);
        Some(v as i32)
    } else {
        let v = i32::from_le_bytes([
            *data.get(idx_off)?,
            *data.get(idx_off + 1)?,
            *data.get(idx_off + 2)?,
            *data.get(idx_off + 3)?,
        ]);
        Some(v)
    }
}
