        }
    }
    if let Ok(home) = std::env::var("HOME") {
        if !home.is_empty() {
            roots.push(PathBuf::from(home).join(".terminfo"));
        }
    }
    if let Ok(dirs) = std::env::var("TERMINFO_DIRS") {
        for d in dirs.split(':') {
            if d.is_empty() {
                roots.push(PathBuf::from("/usr/share/terminfo"));
            } else {
