    };
    let name_size = read_u16(2)? as usize;
    let bool_count = read_u16(4)? as usize;
    let num_count = read_u16(6)? as usize;
    if num_count <= 13 {
        return None;
    }
    let mut off = 12 + name_size + bool_count;
    if off % 2 == 1 {
        off += 1;
    }
    let idx_off = off + 13 * num_size;
    if num_size == 2 {
        let v = i16::from_le_bytes([*data.get(idx_off)?, *data.get(idx_off + 1)?]);
