use crate::highlight::{syntax_for_filename, update_highlight, SyntaxDef};
use crate::row::Row;

#[derive(Debug, Clone)]
struct Snapshot {
    row_chars: Vec<String>,
    cx: usize,
    cy: usize,
    rowoff: usize,
    coloff: usize,
    revision: u64,
}

#[derive(Debug, Clone)]
pub struct TextBuffer {
    pub filename: Option<String>,
    pub rows: Vec<Row>,
    pub cx: usize,
    pub cy: usize,
    pub rowoff: usize,
    pub coloff: usize,
    pub syntax: SyntaxDef,
    revision: u64,
    saved_revision: u64,
    next_revision: u64,
    undo_stack: Vec<Snapshot>,
    redo_stack: Vec<Snapshot>,
    in_edit_unit: bool,
}

fn is_word_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

impl TextBuffer {
    pub fn new(filename: Option<String>, rows: Vec<Row>) -> Self {
        let syntax = syntax_for_filename(filename.as_deref());
        let mut buf = TextBuffer {
            filename,
            rows,
            cx: 0,
            cy: 0,
            rowoff: 0,
            coloff: 0,
            syntax,
            revision: 0,
            saved_revision: 0,
            next_revision: 0,
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),
            in_edit_unit: false,
        };
        buf.refresh_highlight();
        buf
    }

    pub fn new_empty() -> Self {
        Self::new(None, vec![Row::from_edit(String::new())])
    }

    pub fn refresh_highlight(&mut self) {
        update_highlight(&mut self.rows, &self.syntax);
    }

    pub fn select_syntax(&mut self) {
        self.syntax = syntax_for_filename(self.filename.as_deref());
        self.refresh_highlight();
    }

    pub fn filetype(&self) -> &'static str {
        self.syntax.filetype
    }

    pub fn modified(&self) -> bool {
        self.revision != self.saved_revision
    }

    pub fn mark_saved(&mut self) {
        self.saved_revision = self.revision;
        self.in_edit_unit = false;
    }

    fn snapshot(&self) -> Snapshot {
        Snapshot {
            row_chars: self.rows.iter().map(|r| r.chars.clone()).collect(),
            cx: self.cx,
            cy: self.cy,
            rowoff: self.rowoff,
            coloff: self.coloff,
            revision: self.revision,
        }
    }

    fn restore(&mut self, snap: Snapshot) {
        self.rows = snap
            .row_chars
            .into_iter()
            .map(Row::from_edit)
            .collect();
        self.cx = snap.cx;
        self.cy = snap.cy;
        self.rowoff = snap.rowoff;
        self.coloff = snap.coloff;
        self.revision = snap.revision;
        self.refresh_highlight();
    }

    fn start_unit(&mut self) {
        let snap = self.snapshot();
        self.undo_stack.push(snap);
        self.redo_stack.clear();
        self.next_revision += 1;
        self.revision = self.next_revision;
        self.in_edit_unit = true;
    }

    fn start_insert_unit(&mut self) {
        if !self.in_edit_unit {
            self.start_unit();
        }
    }

    pub fn undo(&mut self) -> Option<usize> {
        let snap = self.undo_stack.pop()?;
        let old_cy = self.cy;
        let cur = self.snapshot();
        self.redo_stack.push(cur);
        let new_cy = snap.cy;
        self.restore(snap);
        self.in_edit_unit = false;
        Some(old_cy.min(new_cy))
    }

    pub fn redo(&mut self) -> Option<usize> {
        let snap = self.redo_stack.pop()?;
        let old_cy = self.cy;
        let cur = self.snapshot();
        self.undo_stack.push(cur);
        let new_cy = snap.cy;
        self.restore(snap);
        self.in_edit_unit = false;
        Some(old_cy.min(new_cy))
    }

    pub fn row_len(&self, idx: usize) -> usize {
        self.rows.get(idx).map_or(0, |r| r.len())
    }

    fn current_row_len(&self) -> usize {
        self.row_len(self.cy)
    }

    fn char_at(&self, cy: usize, cx: usize) -> char {
        if cy >= self.rows.len() || cx >= self.row_len(cy) {
            '\n'
        } else {
            self.rows[cy].chars[cx..].chars().next().unwrap_or('\n')
        }
    }

    fn char_at_cursor(&self) -> char {
        self.char_at(self.cy, self.cx)
    }

    // ---- Cursor movement ----
    pub fn move_left(&mut self) {
        if self.cx > 0 {
            let row = &self.rows[self.cy];
            let prev = row.chars[..self.cx].chars().last().unwrap();
            self.cx -= prev.len_utf8();
        } else if self.cy > 0 {
            self.cy -= 1;
            self.cx = self.current_row_len();
        }
    }

    pub fn move_right(&mut self) {
        if self.cy < self.rows.len() {
            let len = self.current_row_len();
            if self.cx < len {
                let c = self.rows[self.cy].chars[self.cx..].chars().next().unwrap();
                self.cx += c.len_utf8();
            } else {
                self.cy += 1;
                self.cx = 0;
            }
        }
    }

    pub fn move_up(&mut self) {
        if self.cy > 0 {
            self.cy -= 1;
            let len = self.current_row_len();
            if self.cx > len {
                self.cx = len;
            }
        }
    }

    pub fn move_down(&mut self) {
        if self.cy < self.rows.len() {
            self.cy += 1;
            let len = self.current_row_len();
            if self.cx > len {
                self.cx = len;
            }
        }
    }

    pub fn move_head(&mut self) {
        self.cx = 0;
    }

    pub fn move_end(&mut self) {
        if self.cy < self.rows.len() {
            self.cx = self.current_row_len();
        }
    }

    pub fn move_page_down(&mut self, text_rows: usize) {
        if text_rows == 0 {
            return;
        }
        self.cy = self.rowoff + text_rows - 1;
        if self.cy > self.rows.len() {
            self.cy = self.rows.len();
        }
        for _ in 0..text_rows {
            self.move_down();
        }
    }

    pub fn move_page_up(&mut self, text_rows: usize) {
        self.cy = self.rowoff;
        for _ in 0..text_rows {
            self.move_up();
        }
    }

    pub fn move_next_word(&mut self) {
        if self.cy >= self.rows.len() {
            return;
        }
        self.move_right();
        while self.cy < self.rows.len() {
            let prev_c = self.char_at_cursor();
            self.move_right();
            if self.cy >= self.rows.len() {
                break;
            }
            let c = self.char_at_cursor();
            if !c.is_whitespace() && is_word_char(prev_c) != is_word_char(c) {
                break;
            }
        }
    }

    fn prev_position(&self, cy: usize, cx: usize) -> Option<(usize, usize)> {
        if cx > 0 {
            let row = &self.rows[cy];
            let prev = row.chars[..cx].chars().last()?;
            Some((cy, cx - prev.len_utf8()))
        } else if cy > 0 {
            Some((cy - 1, self.row_len(cy - 1)))
        } else {
            None
        }
    }

    /// Position returned by the (somewhat idiosyncratic) previous
    /// word operation. If `same_row_only`, do not look before the
    /// current row.
    pub fn prev_word_position(&self, same_row_only: bool) -> Option<(usize, usize)> {
        let mut pos = (self.cy, self.cx);
        // Find the first non-whitespace character before the cursor.
        let q = loop {
            let (py, px) = self.prev_position(pos.0, pos.1)?;
            if same_row_only && py != self.cy {
                return None;
            }
            pos = (py, px);
            let c = self.char_at(py, px);
            if !c.is_whitespace() {
                break pos;
            }
            if py == 0 && px == 0 {
                return Some((0, 0));
            }
        };
        let (qy, qx) = q;
        if qy >= self.rows.len() {
            return Some(q);
        }
        let class = is_word_char(self.char_at(qy, qx));
        let row = &self.rows[qy];
        let mut sx = qx;
        while sx > 0 {
            let prev = row.chars[..sx].chars().last().unwrap();
            if is_word_char(prev) != class {
                break;
            }
            sx -= prev.len_utf8();
        }
        // If the run starts with the second character of the row,
        // the original operation ends up at the row head.
        let chars_before = row.chars[..sx].chars().count();
        if chars_before == 1 {
            sx = 0;
        }
        Some((qy, sx))
    }

    pub fn move_prev_word(&mut self) {
        if let Some((cy, cx)) = self.prev_word_position(false) {
            self.cy = cy;
            self.cx = cx;
        }
    }

    pub fn move_next_paragraph(&mut self) {
        if self.cy >= self.rows.len() {
            self.cx = 0;
            return;
        }
        while self.cy < self.rows.len() && !self.rows[self.cy].is_empty() {
            self.cy += 1;
        }
        while self.cy < self.rows.len() && self.rows[self.cy].is_empty() {
            self.cy += 1;
        }
        self.cx = 0;
    }

    pub fn move_prev_paragraph(&mut self) {
        if self.cy == 0 {
            self.cx = 0;
            return;
        }
        self.cy -= 1;
        while self.cy > 0 && self.rows[self.cy].is_empty() {
            self.cy -= 1;
        }
        while self.cy > 0 && !self.rows[self.cy - 1].is_empty() {
            self.cy -= 1;
        }
        // The loop above can land on an empty row only when the
        // paragraph at the very top follows the row-0-is-empty case;
        // in that situation move back to row 0 itself.
        if self.rows.get(self.cy).map_or(false, |r| r.is_empty()) && self.cy == 0 {
            // stay at 0
        }
        self.cx = 0;
    }

    pub fn move_top(&mut self) {
        self.cy = 0;
    }

    pub fn move_bottom(&mut self) {
        self.cy = self.rows.len();
    }

    // ---- Editing ----
    pub fn insert_char(&mut self, c: char) -> Option<usize> {
        self.start_insert_unit();
        if self.cy == self.rows.len() {
            self.rows.push(Row::from_edit(String::new()));
        }
        let dirty = self.cy;
        self.rows[self.cy].chars.insert(self.cx, c);
        self.rows[self.cy].update_render();
        self.cx += c.len_utf8();
        self.refresh_highlight();
        Some(dirty)
    }

    pub fn insert_newline(&mut self) -> Option<usize> {
        let dirty = self.cy;
        self.start_unit();
        if self.cy == self.rows.len() {
            self.rows
                .insert(self.cy, Row::from_edit(String::new()));
            self.refresh_highlight();
            return Some(dirty);
        }
        if self.cx == 0 {
            self.rows
                .insert(self.cy, Row::from_edit(String::new()));
        } else {
            let rest = self.rows[self.cy].chars[self.cx..].to_string();
            self.rows[self.cy].chars.truncate(self.cx);
            self.rows[self.cy].update_render();
            self.rows.insert(self.cy + 1, Row::from_edit(rest));
        }
        self.cy += 1;
        self.cx = 0;
        self.refresh_highlight();
        Some(dirty)
    }

    fn delete_char_primitive(&mut self) -> Option<usize> {
        if self.cy >= self.rows.len() {
            return None;
        }
        if self.cx == 0 && self.cy == 0 {
            return None;
        }
        if self.cx > 0 {
            let prev_len = {
                let row = &self.rows[self.cy];
                row.chars[..self.cx].chars().last().unwrap().len_utf8()
            };
            self.cx -= prev_len;
            self.rows[self.cy].chars.drain(self.cx..self.cx + prev_len);
            self.rows[self.cy].update_render();
            let dirty = self.cy;
            self.refresh_highlight();
            Some(dirty)
        } else {
            let cur = self.rows.remove(self.cy);
            self.cy -= 1;
            self.cx = self.rows[self.cy].len();
            self.rows[self.cy].chars.push_str(&cur.chars);
            self.rows[self.cy].update_render();
            let dirty = self.cy;
            self.refresh_highlight();
            Some(dirty)
        }
    }

    pub fn delete_char(&mut self) -> Option<usize> {
        if self.cy >= self.rows.len() || (self.cx == 0 && self.cy == 0) {
            return None;
        }
        self.start_unit();
        self.delete_char_primitive()
    }

    pub fn delete_next_char(&mut self) -> Option<usize> {
        if self.cy >= self.rows.len() {
            return None;
        }
        if self.cx >= self.current_row_len() && self.cy + 1 >= self.rows.len() {
            return None;
        }
        self.move_right();
        self.start_unit();
        self.delete_char_primitive()
    }

    pub fn delete_word(&mut self) -> Option<usize> {
        if self.cy >= self.rows.len() || self.cx == 0 {
            return None;
        }
        let (dy, dx) = self.prev_word_position(true)?;
        if dy != self.cy || dx >= self.cx {
            return None;
        }
        self.start_unit();
        self.rows[self.cy].chars.drain(dx..self.cx);
        self.cx = dx;
        self.rows[self.cy].update_render();
        let dirty = self.cy;
        self.refresh_highlight();
        Some(dirty)
    }

    pub fn delete_to_head(&mut self) -> Option<usize> {
        if self.cy >= self.rows.len() || self.cx == 0 {
            return None;
        }
        self.start_unit();
        self.rows[self.cy].chars.drain(..self.cx);
        self.cx = 0;
        self.rows[self.cy].update_render();
        let dirty = self.cy;
        self.refresh_highlight();
        Some(dirty)
    }

    pub fn delete_to_end(&mut self) -> Option<usize> {
        if self.cy >= self.rows.len() {
            return None;
        }
        if self.cx < self.current_row_len() {
            self.start_unit();
            self.rows[self.cy].chars.truncate(self.cx);
            self.rows[self.cy].update_render();
            let dirty = self.cy;
            self.refresh_highlight();
            Some(dirty)
        } else if self.cy + 1 < self.rows.len() {
            self.start_unit();
            let next = self.rows.remove(self.cy + 1);
            self.rows[self.cy].chars.push_str(&next.chars);
            self.rows[self.cy].update_render();
            let dirty = self.cy;
            self.refresh_highlight();
            Some(dirty)
        } else {
            None
        }
    }
}
