    saved_cy: usize,
    saved_rowoff: usize,
    saved_coloff: usize,
    direction: i32,
    cur_row: usize,
    cur_render_byte: usize,
    found: bool,
    advance: bool,
    had_query: bool,
}

enum Flow {
    Continue,
    Quit,
}

pub struct Editor {
    screen: Screen,
    input: InputReader,
    buffers: Vec<TextBuffer>,
    current: usize,
    message: Option<Message>,
    quit_pending: bool,
    pending_first_dirty: bool,
    last_status: Option<String>,
    last_status_row: Option<usize>,
    last_message: Option<(String, bool)>,
