fn truncate_bytes(s: &str, cols: usize) -> &str {
    &s[..s.len().min(cols)]
}

fn open_file_buffer(path: String) -> Result<TextBuffer> {
    match File::open(&path) {
        Ok(file) => {
            let reader = BufReader::new(file);
            let mut rows = Vec::new();
            for line in reader.lines() {
                rows.push(Row::new(line?)?);
            }
            Ok(TextBuffer::new(Some(path), rows))
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(TextBuffer::new(
            Some(path),
            vec![Row::from_edit(String::new())],
        )),
        Err(e) => Err(Error::Io(e)),
    }
}
