#[derive(Default)]
pub struct RenderCtx {
    pub dirty_start: Option<usize>, // file row
    pub status_updated: bool,
    pub message_updated: bool,
}

impl RenderCtx {
    fn dirty_from(&mut self, row: usize) {
        self.dirty_start = Some(match self.dirty_start {
            Some(old) => old.min(row),
            None => row,
        });
    }
    fn dirty_opt(&mut self, row: Option<usize>) {
        if let Some(r) = row {
            self.dirty_from(r);
        }
    }
}

#[derive(Clone)]
struct Message {
    text: String,
    error: bool,
    time: Instant,
}

#[derive(Clone)]
struct SearchVisual {
    query: String,
    current: Option<(usize, usize)>, // row, byte index in render
}

struct SearchState {
    saved_cx: usize,
    saved_cy: usize,
    saved_rowoff: usize,
    saved_coloff: usize,
    direction: i32,
    cur_row: usize,
    cur_render_byte: usize,
    found: bool,
    advance: bool,
    had_query: bool,
}

enum Flow {
    Continue,
    Quit,
}

pub struct Editor {
    screen: Screen,
    input: InputReader,
    buffers: Vec<TextBuffer>,
    current: usize,
    message: Option<Message>,
    quit_pending: bool,
    pending_first_dirty: bool,
    last_status: Option<String>,
    last_status_row: Option<usize>,
    last_message: Option<(String, bool)>,
    last_cursor: Option<(usize, usize)>,
    search_visual: Option<SearchVisual>,
    search_state: Option<SearchState>,
}

impl Editor {
    pub fn new() -> Result<Self> {
        let mut input = InputReader::new();
        let screen = Screen::new(&mut input)?;
        Ok(Editor {
            screen,
            input,
            buffers: Vec::new(),
            current: 0,
            message: None,
            quit_pending: false,
            pending_first_dirty: false,
            last_status: None,
            last_status_row: None,
            last_message: None,
            last_cursor: None,
            search_visual: None,
            search_state: None,
        })
    }

    fn buf(&self) -> &TextBuffer {
        &self.buffers[self.current]
    }

    fn buf_mut(&mut self) -> &mut TextBuffer {
        &mut self.buffers[self.current]
    }

    pub fn init(&mut self, files: Vec<String>) -> Result<()> {
        self.message = Some(Message {
            text: "Ctrl-? for help".to_string(),
            error: false,
            time: Instant::now(),
        });
        if files.is_empty() {
            self.buffers.push(TextBuffer::new_empty());
            self.current = 0;
            self.draw_welcome()?;
            self.pending_first_dirty = true;
        } else {
            for f in files {
                let b = open_file_buffer(f)?;
                self.buffers.push(b);
            }
            self.current = 0;
            let mut ctx = RenderCtx {
                dirty_start: Some(0),
                status_updated: true,
                message_updated: true,
            };
            self.refresh_inner(&mut ctx, false)?;
            self.pending_first_dirty = true;
        }
        Ok(())
    }

    pub fn run(&mut self) -> Result<()> {
        loop {
            let seq = self.input.next_input()?;
            let key = match seq {
                InputSeq::Ignored => continue,
                InputSeq::CursorPosition(..) => {
                    unreachable!()
                }
                InputSeq::Key(k) => k,
            };
            let mut ctx = RenderCtx::default();
            match self.handle_key(key, &mut ctx)? {
                Flow::Quit => break,
                Flow::Continue => {}
            }
            self.refresh_inner(&mut ctx, true)?;
        }
        Ok(())
    }

    fn set_message(&mut self, ctx: &mut RenderCtx, text: impl Into<String>, error: bool) {
        let text = text.into();
        if let Some(m) = &self.message {
            if m.text == text && m.error == error && m.time.elapsed().as_secs() <= 5 {
                return;
            }
        }
        self.message = Some(Message {
            text,
            error,
            time: Instant::now(),
        });
        ctx.message_updated = true;
    }

    fn display_message(&self) -> Option<(String, bool)> {
        let m = self.message.as_ref()?;
        if m.time.elapsed().as_secs() <= 5 {
            Some((m.text.clone(), m.error))
        } else {
            None
        }
    }

    fn format_status(&self) -> String {
        let buf = self.buf();
        let name = buf.filename.as_deref().unwrap_or("[No Name]");
        let mut status = format!("{:?} - {}/{}", name, self.current + 1, self.buffers.len());
        if buf.modified() {
            status.push_str(" (modified)");
        }
        let right = format!(" {} {}/{}", buf.filetype(), buf.cy + 1, buf.rows.len());
        while status.len() < self.screen.cols {
            if self.screen.cols - status.len() == right.len() {
                status.push_str(&right);
                break;
            }
            status.push(' ');
        }
        status
    }

    fn draw_welcome(&mut self) -> Result<()> {
        let cols = self.screen.cols;
        let text_rows = self.screen.text_rows;
        let mut out = String::new();
        out.push_str("\x1b[?25l");
        out.push_str(&self.screen.normal_seq());
        let welcome = format!("Kiro editor -- version {}", VERSION);
        for y in 0..text_rows {
            out.push_str(&format!("\x1b[{}H", y + 1));
            if y == text_rows / 3 {
                let trunc = if welcome.len() > cols {
                    &welcome[..cols]
                } else {
                    &welcome[..]
                };
                let padding = (cols - trunc.len()) / 2;
                if padding > 0 {
                    out.push_str(&self.screen.fg_seq(Highlight::NonText));
                    out.push('~');
                    out.push_str(&self.screen.normal_seq());
                    for _ in 1..padding {
                        out.push(' ');
                    }
                    out.push_str(trunc);
                } else {
                    out.push_str(trunc);
                }
                out.push_str("\x1b[K");
            } else {
                out.push_str(&self.screen.fg_seq(Highlight::NonText));
                out.push('~');
                out.push_str("\x1b[K");
            }
        }
        out.push_str(&self.screen.normal_seq());
        // Status bar.
        let status = self.format_status();
        out.push_str(&format!("\x1b[{}H", text_rows + 1));
        out.push_str("\x1b[7m");
        out.push_str(truncate_bytes(&status, cols));
        out.push_str(&self.screen.normal_seq());
        // Message bar.
        out.push_str(&format!("\x1b[{}H", text_rows + 2));
