        self.last_status_row = Some(text_rows);
        self.last_message = Some(("Ctrl-? for help".to_string(), false));
        self.last_cursor = Some((0, 0));
        Ok(())
    }

    fn draw_row(&self, out: &mut String, screen_y: usize) {
        let buf = self.buf();
        out.push_str(&format!("\x1b[{}H", screen_y + 1));
        let file_row = buf.rowoff + screen_y;
        if file_row >= buf.rows.len() {
            out.push_str(&self.screen.fg_seq(Highlight::NonText));
            out.push('~');
            out.push_str(&self.screen.normal_seq());
            out.push_str("\x1b[K");
            return;
        }
        let row = &buf.rows[file_row];
        let hls = self.row_highlights(file_row, row);
        let chars: Vec<char> = row.render.chars().collect();
        let cols = self.screen.cols;
        let coloff = buf.coloff;
        let mut cur_rx = 0usize;
        let mut cur_hl = Highlight::Normal;
        for (idx, ch) in chars.iter().enumerate() {
            let w = char_width(*ch);
            let start = cur_rx;
            cur_rx += w;
            if start < coloff {
                continue;
            }
            if start >= coloff + cols {
                break;
            }
            if start + w > coloff + cols {
                break;
            }
            let hl = hls.get(idx).copied().unwrap_or(Highlight::Normal);
            if hl != cur_hl {
                if matches!(cur_hl, Highlight::SearchCurrent | Highlight::SearchOther) {
                    out.push_str(&self.screen.normal_seq());
                }
                out.push_str(&self.screen.color_seq(hl));
                cur_hl = hl;
            }
            out.push(*ch);
        }
        out.push_str(&self.screen.normal_seq());
        out.push_str("\x1b[K");
    }

    fn row_highlights(&self, file_row: usize, row: &Row) -> Vec<Highlight> {
        let mut hls = row.hl.clone();
        if hls.len() != row.render.chars().count() {
            hls = vec![Highlight::Normal; row.render.chars().count()];
        }
        if let Some(sv) = &self.search_visual {
            if !sv.query.is_empty() {
                let byte_to_char: Vec<usize> = {
                    let mut v = Vec::new();
                    for (ci, (bi, _)) in row.render.char_indices().enumerate() {
                        while v.len() < bi {
                            v.push(ci);
                        }
                        v.push(ci);
                    }
                    while v.len() <= row.render.len() {
                        v.push(row.render.chars().count());
                    }
                    v
                };
                let mut apply = |hls: &mut Vec<Highlight>, start: usize, end: usize, hlv: Highlight| {
                    let cs = *byte_to_char.get(start).unwrap_or(&0);
                    let ce = *byte_to_char.get(end).unwrap_or(&hls.len());
                    for item in hls.iter_mut().take(ce).skip(cs) {
                        *item = hlv;
                    }
                };
                let mut start = 0usize;
                while start <= row.render.len() {
                    match row.render[start..].find(&sv.query[..]) {
                        Some(rel) => {
                            let s = start + rel;
                            let e = s + sv.query.len();
                            apply(&mut hls, s, e, Highlight::SearchOther);
                            start = e;
                            if sv.query.is_empty() {
                                break;
                            }
                        }
                        None => break,
                    }
                }
                if let Some((crow, cstart)) = sv.current {
                    if crow == file_row {
                        apply(
                            &mut hls,
                            cstart,
                            cstart + sv.query.len(),
                            Highlight::SearchCurrent,
                        );
                    }
                }
            }
        }
        hls
    }

    fn refresh_inner(&mut self, ctx: &mut RenderCtx, main_tick: bool) -> Result<()> {
        let (cols, term_rows) = self.screen.get_window_size(&mut self.input)?;
        validate_size(cols, term_rows)?;
        let size_changed = self.screen.cols != cols || self.screen.term_rows != term_rows;
        if size_changed {
            self.message = None;
        }
        self.screen.cols = cols;
        self.screen.term_rows = term_rows;
        let disp = self.display_message();
        let new_text_rows = term_rows - 1 - if disp.is_some() { 1 } else { 0 };
        let layout_changed = new_text_rows != self.screen.text_rows;
        if layout_changed || size_changed {
            ctx.dirty_start = Some(0);
            ctx.status_updated = true;
        }
        self.screen.text_rows = new_text_rows;
        if main_tick && self.pending_first_dirty {
            ctx.dirty_start = Some(0);
            self.pending_first_dirty = false;
        }

        // Scroll.
        let (rx, cursor_screen, offsets_changed) = {
            let buf = self.buf_mut();
            let old_off = (buf.rowoff, buf.coloff);
            let rx = if buf.cy < buf.rows.len() {
                buf.rows[buf.cy].cx_to_rx(buf.cx)
            } else {
                0
            };
            if buf.cy < buf.rowoff {
                buf.rowoff = buf.cy;
            }
            if buf.cy >= buf.rowoff + new_text_rows {
                buf.rowoff = buf.cy - new_text_rows + 1;
            }
            if rx < buf.coloff {
                buf.coloff = rx;
            }
            if rx >= buf.coloff + cols {
                buf.coloff = rx - cols + 1;
            }
            // Do not let the horizontal offset split a wide
            // character on the cursor row.
            if buf.cy < buf.rows.len() && buf.coloff > 0 {
                let row = &buf.rows[buf.cy];
                let mut crx = 0usize;
                let mut new_off = buf.coloff;
                for ch in row.chars.chars() {
                    let w = if ch == '\t' {
                        crate::row::TAB_STOP - (crx % crate::row::TAB_STOP)
                    } else {
                        char_width(ch)
                    };
                    if buf.coloff > crx && buf.coloff < crx + w {
                        new_off = crx + w;
                        break;
                    }
                    crx += w;
                    if crx >= buf.coloff {
                        break;
                    }
                }
                buf.coloff = new_off;
            }
            let changed = old_off != (buf.rowoff, buf.coloff);
            let cs = (rx - buf.coloff, buf.cy - buf.rowoff);
            (rx, cs, changed)
        };
        let _ = rx;
        if offsets_changed {
            ctx.dirty_start = Some(0);
        }

        let cursor_moved = self.last_cursor != Some(cursor_screen);
        let status_text = self.format_status();
        let status_row = new_text_rows;
        let status_updated = ctx.status_updated
            || self.last_status.as_deref() != Some(status_text.as_str())
            || self.last_status_row != Some(status_row);
        let message_updated = ctx.message_updated || self.last_message != disp;

        let dirty_screen = ctx.dirty_start.and_then(|file_row| {
            let rowoff = self.buf().rowoff;
            let s = file_row.saturating_sub(rowoff);
            if s < new_text_rows {
                Some(s)
            } else {
                None
            }
        });

        if dirty_screen.is_none() && !status_updated && !message_updated {
            if cursor_moved {
                let out = format!(
                    "\x1b[{};{}H",
                    cursor_screen.1 + 1,
                    cursor_screen.0 + 1
                );
                self.screen.write_str_flush(&out)?;
            }
            self.last_status = Some(status_text);
            self.last_status_row = Some(status_row);
            self.last_message = disp;
            self.last_cursor = Some(cursor_screen);
            return Ok(());
        }

        let mut out = String::new();
        out.push_str("\x1b[?25l");
        if let Some(start) = dirty_screen {
            out.push_str(&self.screen.normal_seq());
            for y in start..new_text_rows {
                self.draw_row(&mut out, y);
            }
        }
        if status_updated {
            out.push_str(&format!("\x1b[{}H", status_row + 1));
            out.push_str("\x1b[7m");
            out.push_str(&status_text[..status_text.len().min(cols)]);
            out.push_str(&self.screen.normal_seq());
        }
        if message_updated {
            if let Some((text, error)) = &disp {
                out.push_str(&format!("\x1b[{}H", term_rows));
                if *error {
                    out.push_str(&self.screen.error_seq());
                }
                out.push_str(truncate_bytes(text, cols));
                if *error {
                    out.push_str(&self.screen.normal_seq());
                }
                out.push_str("\x1b[K");
            }
        }
        out.push_str(&format!(
            "\x1b[{};{}H",
            cursor_screen.1 + 1,
            cursor_screen.0 + 1
        ));
        out.push_str("\x1b[?25h");
        self.screen.write_str_flush(&out)?;
        self.last_status = Some(status_text);
        self.last_status_row = Some(status_row);
        self.last_message = disp;
        self.last_cursor = Some(cursor_screen);
        Ok(())
    }
}
