impl Editor {
    fn handle_key(&mut self, key: Key, ctx: &mut RenderCtx) -> Result<Flow> {
        if key != Key::Ctrl('q') {
            self.quit_pending = false;
        }
        match key {
            Key::Ctrl('q') => {
                let any_dirty = self.buffers.iter().any(|b| b.modified());
                if any_dirty && !self.quit_pending {
                    self.quit_pending = true;
                    self.set_message(
                        ctx,
                        "At least one file has unsaved changes! Press ^Q again to quit or ^S to save",
                        true,
                    );
                    Ok(Flow::Continue)
                } else {
                    Ok(Flow::Quit)
                }
            }
            Key::Ctrl('s') => {
                self.save(ctx)?;
                Ok(Flow::Continue)
            }
            Key::Ctrl('o') => {
                self.open_prompt(ctx)?;
                Ok(Flow::Continue)
            }
            Key::Ctrl('x') => {
                self.next_buffer(ctx, true);
                Ok(Flow::Continue)
            }
            Key::Alt('x') => {
                self.next_buffer(ctx, false);
                Ok(Flow::Continue)
            }
            Key::Ctrl('p') | Key::Up => {
                self.buf_mut().move_up();
                Ok(Flow::Continue)
            }
            Key::Ctrl('n') | Key::Down => {
                self.buf_mut().move_down();
                Ok(Flow::Continue)
            }
            Key::Ctrl('f') | Key::Right => {
                self.buf_mut().move_right();
                Ok(Flow::Continue)
            }
            Key::Ctrl('b') | Key::Left => {
                self.buf_mut().move_left();
                Ok(Flow::Continue)
            }
            Key::Ctrl('a') | Key::Home => {
                self.buf_mut().move_head();
                Ok(Flow::Continue)
            }
            Key::Ctrl('e') | Key::End => {
                self.buf_mut().move_end();
                Ok(Flow::Continue)
            }
            // The following two pager mappings reproduce the
            // behaviour of the original binary (which is the
            // opposite of what its help text says for the
            // Ctrl-[ / Ctrl-] keys).
            Key::Escape | Key::Alt('v') | Key::PageUp => {
                let rows = self.screen.text_rows;
                self.buf_mut().move_page_up(rows);
                Ok(Flow::Continue)
            }
            Key::Ctrl(']') | Key::Ctrl('v') | Key::PageDown => {
                let rows = self.screen.text_rows;
                self.buf_mut().move_page_down(rows);
                Ok(Flow::Continue)
