    fn next_buffer(&mut self, ctx: &mut RenderCtx, forward: bool) {
        if self.buffers.len() <= 1 {
            self.set_message(ctx, "No other buffer is opened", false);
            return;
        }
        if forward {
            self.current = (self.current + 1) % self.buffers.len();
        } else {
            self.current = (self.current + self.buffers.len() - 1) % self.buffers.len();
        }
        ctx.dirty_start = Some(0);
        ctx.status_updated = true;
    }

    fn save(&mut self, ctx: &mut RenderCtx) -> Result<()> {
        let path = match self.buf().filename.clone() {
            Some(p) => p,
            None => {
                let Some(input) = self.prompt(ctx, "Save as: %s (^G or ESC to cancel)", false)?
                else {
                    return Ok(());
                };
                if input.is_empty() {
                    return Ok(());
                }
                input
            }
        };
        let contents = self
            .buf()
            .rows
            .iter()
            .map(|r| format!("{}\n", r.chars))
            .collect::<String>();
        match std::fs::write(&path, contents.as_bytes()) {
            Ok(()) => {
                let bytes = contents.len();
                let buf = self.buf_mut();
                buf.filename = Some(path.clone());
                buf.select_syntax();
                buf.mark_saved();
                ctx.dirty_start = Some(0);
                ctx.status_updated = true;
                self.set_message(ctx, format!("{} bytes written to {}", bytes, path), false);
            }
            Err(e) => {
                self.set_message(ctx, format!("Could not save: {}", e), true);
            }
        }
        Ok(())
    }

    fn open_prompt(&mut self, ctx: &mut RenderCtx) -> Result<()> {
        let Some(input) = self.prompt(
            ctx,
            "Open: %s (Empty name for new text buffer, ^G or ESC to cancel)",
            false,
        )?
        else {
            self.set_message(ctx, "Canceled", false);
            return Ok(());
        };
        if input.is_empty() {
            self.buffers.push(TextBuffer::new_empty());
        } else {
            let b = open_file_buffer(input)?;
            self.buffers.push(b);
        }
        self.current = self.buffers.len() - 1;
        self.message = None;
        ctx.dirty_start = Some(0);
        ctx.status_updated = true;
        Ok(())
    }

    fn show_help(&mut self, ctx: &mut RenderCtx) -> Result<()> {
        self.draw_help()?;
        let _ = self.input.next_input()?;
        ctx.dirty_start = Some(0);
        Ok(())
    }

    fn draw_help(&mut self) -> Result<()> {
        let cols = self.screen.cols;
        let text_rows = self.screen.text_rows;
        let lines: Vec<(String, String)> = HELP_ITEMS
            .iter()
            .map(|(k, d)| (format!("{:<30}", k), format!(": {}", d)))
            .collect();
        let max_len = lines
            .iter()
            .map(|(a, b)| a.len() + b.len())
            .max()
            .unwrap_or(0);
        let xpad = cols.saturating_sub(max_len) / 2;
        let ypad = text_rows.saturating_sub(lines.len()) / 2;
        let mut out = String::new();
        for y in 0..text_rows {
            out.push_str(&format!("\x1b[{}H", y + 1));
            if y < ypad || y >= ypad + lines.len() {
                out.push_str("\x1b[K");
                continue;
            }
            let (name, desc) = &lines[y - ypad];
            let mut rem = cols;
            let pre = xpad.min(rem);
            for _ in 0..pre {
                out.push(' ');
            }
            rem -= pre;
            if rem > 0 {
                let take = name.len().min(rem);
                out.push_str(&self.screen.fg_seq(Highlight::Special));
                out.push_str(&name[..take]);
                out.push_str(&self.screen.normal_seq());
                rem -= take;
                if rem > 0 {
                    let dtake = desc.len().min(rem);
                    out.push_str(&desc[..dtake]);
                }
            }
            out.push_str("\x1b[K");
        }
        self.screen.write_str_flush(&out)
    }

    fn search(&mut self, ctx: &mut RenderCtx) -> Result<()> {
        // Initialise search state. Accessing the first row here
        // mirrors the original behaviour for an empty buffer.
        if self.buf().rows.is_empty() {
            let _row = &self.buf().rows[0];
        }
        let (scx, scy, sro, sco, cur_row, cur_rb) = {
            let b = self.buf();
            let cur_row = if b.rows.is_empty() {
                0
            } else {
                b.cy % b.rows.len()
            };
            let cur_rb = if b.cy < b.rows.len() {
                b.rows[b.cy].cx_to_render_byte(b.cx)
            } else {
                0
            };
            (b.cx, b.cy, b.rowoff, b.coloff, cur_row, cur_rb)
        };
        self.search_state = Some(SearchState {
            saved_cx: scx,
            saved_cy: scy,
            saved_rowoff: sro,
            saved_coloff: sco,
            direction: 1,
            cur_row,
            cur_render_byte: cur_rb,
            found: false,
            advance: false,
            had_query: false,
        });
        let result = self.prompt(
            ctx,
            "Search: %s (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)",
            true,
        )?;
        let state = self.search_state.take().unwrap();
        self.search_visual = None;
        let restore = |this: &mut Self| {
            let b = this.buf_mut();
            b.cx = state.saved_cx;
            b.cy = state.saved_cy;
            b.rowoff = state.saved_rowoff;
            b.coloff = state.saved_coloff;
        };
        match result {
            None => {
                restore(self);
                if state.had_query {
                    ctx.dirty_start = Some(0);
                }
                self.set_message(ctx, "Canceled", false);
            }
            Some(q) if q.is_empty() => {
                restore(self);
                if state.had_query {
                    ctx.dirty_start = Some(0);
                }
                self.set_message(ctx, "Canceled", false);
            }
            Some(_) if state.found => {
                ctx.dirty_start = Some(0);
                self.set_message(ctx, "Found", false);
            }
            Some(_) => {
                restore(self);
                if state.had_query {
                    ctx.dirty_start = Some(0);
                }
                self.set_message(ctx, "Not found", false);
            }
        }
        Ok(())
    }

    fn do_search(&mut self, query: &str, ctx: &mut RenderCtx) {
        let Some(mut state) = self.search_state.take() else {
            return;
        };
        if query.is_empty() {
            if self
                .search_visual
                .as_ref()
                .map_or(false, |v| !v.query.is_empty())
            {
                ctx.dirty_start = Some(0);
            }
            state.found = false;
            self.search_visual = Some(SearchVisual {
                query: String::new(),
                current: None,
            });
            self.search_state = Some(state);
            return;
        }
        state.had_query = true;
        ctx.dirty_start = Some(0);
        let mut found: Option<(usize, usize)> = None;
        {
            let buf = self.buf();
            let num = buf.rows.len();
            if state.direction >= 0 {
                let mut start_idx = state.cur_render_byte;
                if state.advance {
                    let row = &buf.rows[state.cur_row];
                    if start_idx < row.render.len() {
                        start_idx += row.render[start_idx..]
                            .chars()
                            .next()
                            .map_or(0, |c| c.len_utf8());
                    }
                }
                for off in 0..num {
                    let r = (state.cur_row + off) % num;
                    let hay_start = if off == 0 { start_idx } else { 0 };
                    if hay_start > buf.rows[r].render.len() {
                        continue;
                    }
                    if let Some(rel) = buf.rows[r].render[hay_start..].find(query) {
                        found = Some((r, hay_start + rel));
                        break;
                    }
                }
            } else {
                for off in 0..num {
                    let r = (state.cur_row + num - (off % num)) % num;
                    let hay_end = if off == 0 {
                        state.cur_render_byte.min(buf.rows[r].render.len())
                    } else {
                        buf.rows[r].render.len()
                    };
                    if let Some(pos) = buf.rows[r].render[..hay_end].rfind(query) {
                        found = Some((r, pos));
                        break;
                    }
                }
            }
        }
        state.advance = false;
        if let Some((r, pos)) = found {
            state.cur_row = r;
            state.cur_render_byte = pos;
            state.found = true;
            let b = self.buf_mut();
            b.cy = r;
            b.cx = b.rows[r].render_byte_to_cx(pos);
            self.search_visual = Some(SearchVisual {
                query: query.to_string(),
                current: Some((r, pos)),
            });
        } else {
            state.found = false;
            self.search_visual = Some(SearchVisual {
                query: query.to_string(),
                current: None,
            });
        }
        self.search_state = Some(state);
    }

    fn prompt(
        &mut self,
        main_ctx: &mut RenderCtx,
        template: &str,
        is_search: bool,
    ) -> Result<Option<String>> {
        let mut input = String::new();
        let mut pending_search = is_search;
        let prefix_len = template.find("%s").unwrap_or(template.len());
        let result;
        loop {
            let mut local_ctx = RenderCtx::default();
            if is_search && pending_search {
                self.do_search(&input.clone(), &mut local_ctx);
                pending_search = false;
            }
            let prompt_text = template.replacen("%s", &input, 1);
            self.message = Some(Message {
                text: prompt_text,
                error: false,
                time: Instant::now(),
            });
            local_ctx.message_updated = true;
            self.refresh_inner(&mut local_ctx, false)?;
            let input_width: usize = input.chars().map(char_width).sum();
            let col = prefix_len + input_width + 1;
            let goto = format!("\x1b[{};{}H", self.screen.term_rows, col);
            self.screen.write_str_flush(&goto)?;

            let key = loop {
                match self.input.next_input()? {
                    InputSeq::Key(k) => break k,
                    _ => continue,
                }
            };
            match key {
                Key::Ctrl('m') => {
                    result = Some(input);
                    break;
                }
                Key::Ctrl('g') | Key::Ctrl('q') | Key::Escape => {
                    result = None;
                    break;
                }
                Key::Ctrl('h') | Key::Backspace | Key::Delete => {
                    input.pop();
                    pending_search = is_search;
                }
                Key::Ctrl('w') => {
                    delete_word_in_input(&mut input);
                    pending_search = is_search;
                }
                Key::Ctrl('j') => {
                    input.clear();
                    pending_search = is_search;
                }
                Key::Ctrl('k') => {}
                Key::Right | Key::Down | Key::Ctrl('f') | Key::Ctrl('n') if is_search => {
                    if let Some(st) = &mut self.search_state {
                        st.direction = 1;
                        st.advance = true;
                    }
                    pending_search = true;
                }
                Key::Left | Key::Up | Key::Ctrl('b') | Key::Ctrl('p') if is_search => {
                    if let Some(st) = &mut self.search_state {
                        st.direction = -1;
                        st.advance = false;
                    }
                    pending_search = true;
                }
                Key::Char(c) if !c.is_control() => {
                    input.push(c);
                    pending_search = is_search;
                }
                Key::Alt(c) if !c.is_control() && c != '\x7f' => {
                    input.push(c);
                    pending_search = is_search;
                }
                _ => {
                    if is_search {
                        pending_search = true;
                    }
                }
            }
        }
        self.set_message(main_ctx, "", false);
        Ok(result)
    }
}

fn delete_word_in_input(input: &mut String) {
    if input.is_empty() {
        return;
    }
    let mut tmp = TextBuffer::new(None, vec![Row::from_edit(input.clone())]);
    tmp.cx = input.len();
    tmp.cy = 0;
    if let Some((_, dx)) = tmp.prev_word_position(true) {
        input.drain(dx..);
    }
}
