                Key::Ctrl('w') => {
                    delete_word_in_input(&mut input);
                    pending_search = is_search;
                }
                Key::Ctrl('j') => {
                    input.clear();
                    pending_search = is_search;
                }
                Key::Ctrl('k') => {}
                Key::Right | Key::Down | Key::Ctrl('f') | Key::Ctrl('n') if is_search => {
                    if let Some(st) = &mut self.search_state {
                        st.direction = 1;
                        st.advance = true;
                    }
                    pending_search = true;
                }
                Key::Left | Key::Up | Key::Ctrl('b') | Key::Ctrl('p') if is_search => {
                    if let Some(st) = &mut self.search_state {
                        st.direction = -1;
                        st.advance = false;
                    }
                    pending_search = true;
                }
                Key::Char(c) if !c.is_control() => {
                    input.push(c);
                    pending_search = is_search;
                }
                Key::Alt(c) if !c.is_control() && c != '\x7f' => {
                    input.push(c);
                    pending_search = is_search;
                }
                _ => {
                    if is_search {
                        pending_search = true;
                    }
                }
            }
        }
        self.set_message(main_ctx, "", false);
        Ok(result)
    }
}

fn delete_word_in_input(input: &mut String) {
    if input.is_empty() {
        return;
    }
    let mut tmp = TextBuffer::new(None, vec![Row::from_edit(input.clone())]);
    tmp.cx = input.len();
    tmp.cy = 0;
    if let Some((_, dx)) = tmp.prev_word_position(true) {
        input.drain(dx..);
    }
}
