new='''    fn refresh_inner(&mut self, ctx: &mut RenderCtx, main_tick: bool) -> Result<()> {
        let (cols, term_rows) = self.screen.get_window_size(&mut self.input)?;
        validate_size(cols, term_rows)?;
        let size_changed = self.screen.cols != cols || self.screen.term_rows != term_rows;
        if size_changed {
            if main_tick {
                self.message = None;
            }
            self.screen.cols = cols;
            self.screen.term_rows = term_rows;
            self.screen.text_rows = if main_tick {
                term_rows - 1
            } else {
                term_rows - 2
            };
        }
        // Scroll using the (possibly newly updated) physical
        // width, but with the text-row count from the previous
        // message-bar layout. The message-bar layout itself is
        // updated below, after scrolling.
        let (_rx, cursor_screen, offsets_changed) =
            self.scroll_buffer(self.screen.text_rows, cols);
        let disp = self.display_message();
        let new_text_rows = term_rows - 1 - if disp.is_some() { 1 } else { 0 };
        let layout_changed = new_text_rows != self.screen.text_rows;
        if size_changed {
            ctx.dirty_start = Some(0);
            ctx.status_updated = true;
        } else if layout_changed {
            ctx.status_updated = true;
            if new_text_rows > self.screen.text_rows {
                // Only the newly exposed rows at the bottom need
                // to be drawn when the message bar goes away.
                let first_new = self.buf().rowoff + self.screen.text_rows;
                ctx.dirty_from(first_new);
            }
        }
        self.screen.text_rows = new_text_rows;
        if main_tick && self.pending_first_dirty {
            ctx.dirty_start = Some(0);
            self.pending_first_dirty = false;
        }
        if offsets_changed {
            ctx.dirty_start = Some(0);
        }

'''
