new='''        let rows_content: Vec<String> = self
            .buf()
            .rows
            .iter()
            .map(|r| format!("{}\\n", r.chars))
            .collect();
        let total_bytes: usize = rows_content.iter().map(|r| r.len()).sum();
        ctx.status_updated = true;
        // The original distinguishes errors while writing from
        // errors when flushing its buffered writer.
        enum SaveOutcome {
            Saved,
            SaveError(std::io::Error),
            FlushError(std::io::Error),
        }
        let outcome = match std::fs::File::create(&path) {
            Ok(file) => {
                use std::io::Write;
                let mut writer = std::io::BufWriter::new(file);
                let mut result = SaveOutcome::Saved;
                for chunk in &rows_content {
                    if let Err(e) = writer.write_all(chunk.as_bytes()) {
                        result = SaveOutcome::SaveError(e);
                        break;
                    }
                }
                if matches!(result, SaveOutcome::Saved) {
                    if let Err(e) = writer.flush() {
                        result = SaveOutcome::FlushError(e);
                    }
                }
                result
            }
            Err(e) => SaveOutcome::SaveError(e),
        };
        match outcome {
            SaveOutcome::Saved => {
                let bytes = total_bytes;
                let old_filetype = self.buf().filetype();
                let buf = self.buf_mut();
                buf.filename = Some(path.clone());
                buf.select_syntax();
                let new_filetype = buf.filetype();
                buf.mark_saved();
                if old_filetype != new_filetype {
                    ctx.dirty_start = Some(0);
                }
                self.set_message(ctx, format!("{} bytes written to {}", bytes, path), false);
            }
            SaveOutcome::SaveError(e) => {
                self.set_message(ctx, format!("Could not save: {}", e), true);
            }
            SaveOutcome::FlushError(e) => {
                self.set_message(ctx, format!("Could not flush to file: {}", e), true);
            }
        }
'''
# But this is_save_as status logic: our current code sets ctx.status_updated only if is_save_as before match. This replacement sets always - need adjust after.
s=s[:old_start]+new+s[old_end:]
# fix status logic: replace the ctx.status_updated=true we just put with conditional to preserve earlier behavior
s=s.replace("        ctx.status_updated = true;\n        // The original distinguishes", "        if is_save_as {\n            ctx.status_updated = true;\n        }\n        // The original distinguishes")
p.write_text(s)
print("patched")
