    let mut state = HlState::default();
    if syntax.filetype == "plain" {
        for row in rows.iter_mut() {
            row.hl = vec![Highlight::Normal; row.render.chars().count()];
        }
        return;
    }
    for row in rows.iter_mut() {
        row.hl = compute_row(&row.render, syntax, &mut state);
    }
}"""
new="""pub fn update_highlight(rows: &mut [Row], syntax: &SyntaxDef) {
    update_highlight_from(rows, syntax, 0);
}

pub fn update_highlight_from(rows: &mut [Row], syntax: &SyntaxDef, start: usize) {
    if syntax.filetype == "plain" {
        for row in rows.iter_mut() {
            row.hl = vec![Highlight::Normal; row.render.chars().count()];
            row.hl_state = HlState::default();
        }
        return;
    }
