        let old_state = row.hl_state;
        row.hl = compute_row(&row.render, syntax, &mut state);
        row.hl_state = state;
        if state == old_state {
            // Following rows start from the same state as before,
            // so their highlighting cannot change.
            break;
        }
    }
}"""
