            render: String::new(),
            hl: Vec::new(),
            hl_state: HlState::default(),
            chars,
        };""")
p.write_text(s)
# buffer refresh_highlight_from and replace call sites contextually
p=pathlib.Path("src/buffer.rs"); s=p.read_text()
s=s.replace("use crate::highlight::{syntax_for_filename, update_highlight, SyntaxDef};", "use crate::highlight::{syntax_for_filename, update_highlight, update_highlight_from, SyntaxDef};")
s=s.replace("""    pub fn refresh_highlight(&mut self) {
        update_highlight(&mut self.rows, &self.syntax);
    }""", """    pub fn refresh_highlight(&mut self) {
        update_highlight(&mut self.rows, &self.syntax);
    }

    fn refresh_highlight_from(&mut self, start: usize) {
        update_highlight_from(&mut self.rows, &self.syntax, start);
    }""")
